exercises.solution:
mkdir -p ~/lab
{
  echo "== $(hostname)"; ~/bin/srodowisko.sh
  for h in srv-test app01; do echo "== $h"; ssh -o BatchMode=yes "$h" 'bash -s' < ~/bin/srodowisko.sh; done
} | tee ~/lab/srodowiska.txt

awk '
  /^==/ { h = $2; hosts[++n] = h; next }
  { k = $1; $1 = ""; sub(/^ +/, ""); v[k, h] = $0; keys[k] = 1 }
  END {
    printf "%-6s", ""; for (i = 1; i <= n; i++) printf " %-16s", hosts[i]; print ""
    split("virt cpu ram heap tz", p, " ")
    for (j = 1; j <= 5; j++) { printf "%-6s", p[j]; for (i = 1; i <= n; i++) printf " %-16s", v[p[j], hosts[i]]; print "" }
  }' ~/lab/srodowiska.txt

mkdir -p ~/lab/pamiec && cd ~/lab/pamiec
cat > Duzo.java <<'EOF'
import java.util.ArrayList;
import java.util.List;
public class Duzo {
  public static void main(String[] a) {
    List<byte[]> dane = new ArrayList<>();
    for (int i = 0; i < 120; i++) dane.add(new byte[10 * 1024 * 1024]);
    System.out.println("zaladowano " + dane.size() * 10 + " MB");
  }
}
EOF
java Duzo.java
java -XX:MaxRAM=2g Duzo.java 2>&1 | tail -1
